import type { FoundationLessonData } from "@/data/foundations/types";

export type TeachingDefinition = {
  term: string;
  meaning: string;
  example: string;
  doNotConfuse: string;
};

type VocabularyEntry = TeachingDefinition & {
  track: string;
  aliases: string[];
  core?: boolean;
};

const entry = (
  track: string,
  term: string,
  meaning: string,
  example: string,
  doNotConfuse: string,
  aliases: string[],
  core = false
): VocabularyEntry => ({ track, term, meaning, example, doNotConfuse, aliases, core });

