const normalize = (value: string) => value.toLowerCase().replace(/[^a-z0-9+]+/g, " ").trim().replace(/\s+/g, " ");

export function selectTeachingDefinitions(topicId: string, lesson: FoundationLessonData): TeachingDefinition[] {
  const track = topicId.split("/")[0];
  const haystack = normalize([
    topicId,
    lesson.summary,
    lesson.keyIdea,
    ...lesson.outcomes,
    ...lesson.conceptMap,
    ...lesson.theory.flatMap((section) => [section.heading, section.body]),
    lesson.example.title,
    lesson.example.explanation,
    ...lesson.failureModes,
    ...lesson.flashcards.flatMap((card) => [card.front, card.back]),
    ...lesson.revision,
    lesson.question.prompt,
    lesson.question.answer
  ].join(" "));
  const paddedHaystack = ` ${haystack} `;

  const selected = vocabulary.filter((item) => item.track === track && item.aliases.some((alias) => paddedHaystack.includes(` ${normalize(alias)} `)));
  return selected.map(({ term, meaning, example, doNotConfuse }) => ({ term, meaning, example, doNotConfuse }));
}
